function chooseFresh(items,amount,domain,key=value=>value?.id||value?.q||String(value)){
 const unique=[...new Map(items.map(item=>[key(item),item])).values()],recent=state.exerciseRotation[domain]||[],fresh=unique.filter(item=>!recent.includes(key(item))),pool=fresh.length>=amount?fresh:unique;
 const chosen=sample(pool,Math.min(amount,pool.length)),keys=chosen.map(key);
 state.exerciseRotation[domain]=[...recent.filter(id=>!keys.includes(id)),...keys].slice(-Math.max(amount*4,12));persist();return chosen;
}
function freshMemory(){let exercise=makeMemoryExercise(),recent=state.exerciseRotation.memoria||[];for(let i=0;i<30&&recent.includes(exercise.variant);i++)exercise=makeMemoryExercise();state.exerciseRotation.memoria=[...recent.filter(x=>x!==exercise.variant),exercise.variant].slice(-8);persist();return exercise;}
function adaptiveChoice(pool=state.favorites){const hour=new Date().getHours(),scores=Object.fromEntries(pool.map(id=>[id,10])),cognitive=['matematica','logica','memoria','scacchi'],calm=['lettura','preghiera','respirazione','meditazione'];let reason='per dare varietà al tuo percorso';
 const add=(ids,value)=>ids.filter(id=>scores[id]!==undefined).forEach(id=>scores[id]+=value);
 if(shortcutContext==='work'){add(['logica','matematica','memoria','respirazione'],8);reason='adatto a una pausa di lavoro';}
 else if(shortcutContext==='break'){add(['respirazione','memoria','lettura'],8);reason='adatto a una pausa breve';}
 else if(shortcutContext==='bedtime'){add(['lettura','respirazione','meditazione'],12);reason='più adatto a fine giornata';}
 else if(hour>=6&&hour<12){add(cognitive,6);reason='scelto per attivare l’attenzione al mattino';}
 else if(hour>=21||hour<6){add(calm,9);reason='scelto per accompagnare un ritmo più calmo';}
 else {add(['logica','memoria','respirazione'],4);reason='scelto per una pausa durante la giornata';}
 const cutoff=Date.now()-30*60*1000,rapid=state.timo.events.filter(e=>e.type==='access'&&new Date(e.at).getTime()>cutoff).length;
 if(rapid>=3){add(['respirazione','meditazione'],14);add(['lettura'],5);reason='scelto dopo più aperture ravvicinate';}
 if(state.timo.life<40){add(['respirazione','meditazione','lettura'],6);reason='breve e accessibile per ridare energia a Timo';}
 if(availableMinutes&&availableMinutes<=2){add(['respirazione','meditazione','memoria'],10);reason='compatibile con il tempo disponibile';}
 const recent=state.history.slice(-10);for(const id of pool){const seen=recent.filter(x=>x.domain===id).length;scores[id]+=Math.max(0,4-seen)*1.5;if(id===state.lastRecommendation)scores[id]*=.2;}
 const entries=Object.entries(scores),sum=entries.reduce((n,[,v])=>n+v,0);let draw=Math.random()*sum,chosen=entries[0]?.[0]||'lettura';for(const [id,weight] of entries){draw-=weight;if(draw<=0){chosen=id;break;}}
 return {id:chosen,reason,scores};}
const recommend=()=>{const pool=readableDomains(state.favorites);if(!state.nextRecommendation||!pool.includes(state.nextRecommendation)){const choice=adaptiveChoice(pool.length?pool:state.favorites);state.nextRecommendation=choice.id;state.nextRecommendationReason=choice.reason;}return state.nextRecommendation;};
const adaptiveDirectChoice=()=>{const withReadableBook=readableDomains(state.favorites);return adaptiveChoice(withReadableBook.length?withReadableBook:state.favorites);};
const resistanceProfiles={1:{questions:3,pages:2,minutes:3,label:'Leggera'},2:{questions:4,pages:3,minutes:3,label:'Consapevole'},3:{questions:5,pages:5,minutes:3,label:'Profonda'},4:{questions:7,pages:7,minutes:3,label:'Recupero'}};
function dailyRow(at=new Date()){const key=dayKey(at),empty={sessions:0,practiceSeconds:0,directCompleted:0,accessAttempts:0,socialMinutes:0,timoDelta:0,correct:0,answers:0,resistanceTotal:0,resistanceSessions:0,grantsUsed:0,domains:{}};state.daily=state.daily||{};state.daily[key]={...empty,...state.daily[key],domains:{...(state.daily[key]?.domains||{})}};return state.daily[key];}
function resistanceLevel(){let level=state.timo.life>70?1:state.timo.life>40?2:state.timo.life>15?3:4;const cutoff=Date.now()-30*60*1000,recent=state.timo.events.filter(e=>e.type==='access'&&new Date(e.at).getTime()>cutoff).length;if(recent>=5)level=4;else if(recent>=3)level=Math.min(4,level+1);return level;}
function directProfile(){const level=resistanceLevel();return {level,...resistanceProfiles[level]};}
function timoEvent(type,delta,meta={}){state.timo.life=Math.min(100,Math.max(0,state.timo.life+delta));if(type==='access')state.timo.attempts++;if(type==='social')state.timo.socialMinutes+=meta.minutes||0;const at=new Date().toISOString();state.timo.events.push({type,delta,at,...meta});state.timo.events=state.timo.events.slice(-500);const day=dailyRow(new Date(at));if(type==='access')day.accessAttempts++;if(type==='social')day.socialMinutes+=meta.minutes||0;day.timoDelta+=delta;persist();}
/* ===== Regole dell’energia di Timo =====
   Pensate per essere difficili da aggirare: le perdite crescono con la ripetizione, i guadagni dipendono dalla qualità
   e diminuiscono se si accumulano allenamenti solo per “ricaricare” Timo. */
const TIMO={accessSteps:[4,6,9,12,15],nightFactor:1.5,bypass:8,abandon:3,inactiveDay:6,dailyGainCap:35,diminishing:[1,1,.7,.5,.25],base:{cognitive:10,readingQuiz:10,reading:5,practice:6},perfect:3,trigger:4};
const isNight=(d=new Date())=>d.getHours()>=23||d.getHours()<6;
function accessPenalty(){const now=Date.now(),recent=state.timo.events.filter(e=>e.type==='access'&&now-new Date(e.at).getTime()<60*60*1000).length;let d=TIMO.accessSteps[Math.min(recent,TIMO.accessSteps.length-1)];const night=isNight();if(night)d=Math.round(d*TIMO.nightFactor);return {delta:-d,note:`${recent?`${recent+1}ª apertura in un’ora`:'Apertura'}${night?' · di notte':''}`};}
function registerAccess(app){const p=accessPenalty();timoEvent('access',p.delta,{app,note:p.note});}
const socialCost=m=>(m>15?Math.ceil((Math.min(m,30)-15)/2):0)+(m>30?Math.min(m,60)-30:0)+(m>60?(m-60)*2:0);
function reportSocial(minutes,appId){if(!social[appId]||!minutes)return;const before=dailyRow().socialMinutes||0,delta=-(socialCost(before+minutes)-socialCost(before));timoEvent('social',delta,{minutes,app:appId,note:`${minutes} min su ${social[appId].name} · oggi ${before+minutes} min`});}
function streakDays(){let n=0;for(let i=1;i<90;i++){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-i);const r=state.daily?.[dayKey(d)];if(r?.sessions>0&&(r.socialMinutes||0)<=30)n++;else break;}return n+1;}
function applyInactivity(){const today=dayKey();if(!state.timo.lastDecayDay){state.timo.lastDecayDay=today;return;}if(state.timo.lastDecayDay===today)return;const d=new Date(state.timo.lastDecayDay+'T12:00:00');let guard=0;d.setDate(d.getDate()+1);while(dayKey(d)<today&&guard++<7){const key=dayKey(d);if(!(state.daily?.[key]?.sessions>0))timoEvent('inactive',-TIMO.inactiveDay,{day:key,note:`Nessun allenamento il ${d.toLocaleDateString('it-IT',{day:'numeric',month:'long'})}`});d.setDate(d.getDate()+1);}state.timo.lastDecayDay=today;persist();}
function trainingGain(s){const cognitive=['matematica','logica','memoria','scacchi'].includes(s.domain),reading=readingDomains.includes(s.domain),quiz=reading&&s.quizMode&&!s.quizSkipped,notes=[];
 let g=cognitive?TIMO.base.cognitive:quiz?TIMO.base.readingQuiz:reading?TIMO.base.reading:TIMO.base.practice;
 if(reading&&!quiz)notes.push(s.quizSkipped?'Domande saltate: metà energia':'Senza domande di verifica: metà energia');
 if(cognitive||quiz){const n=s.questions?.length||s.totalRounds||3,acc=s.attempts?s.correct/s.attempts:0;if(s.correct>=n&&s.attempts===n){g+=TIMO.perfect;notes.push(`+${TIMO.perfect} tutto giusto al primo tentativo`);}else if(acc<.5){g=Math.round(g/2);notes.push('Dimezzata: troppi tentativi');}}
 if(cognitive&&s.seconds<8*(s.questions?.length||s.totalRounds||3))return {gain:0,streak:0,notes:['Troppo veloce per contare: prenditi il tempo di ragionare.']};
 if(reading){const pages=Math.max(1,(s.pagesRead||[]).length);if(s.seconds/pages<15){g=Math.round(g*.3);notes.push('Lettura troppo rapida');}}
 if(s.trigger&&g>0){g+=TIMO.trigger;notes.push(`+${TIMO.trigger} impulso trasformato in allenamento`);}
 const prior=state.history.filter(h=>Date.now()-new Date(h.at).getTime()<24*60*60*1000).length,f=TIMO.diminishing[Math.min(prior,TIMO.diminishing.length-1)];if(f<1&&g>0){g=Math.max(1,Math.round(g*f));notes.push(`Ridotta al ${Math.round(f*100)}%: ${prior+1}ª sessione in 24 ore`);}
 const gainedToday=state.timo.events.filter(e=>e.type==='training'&&dayKey(new Date(e.at))===dayKey()).reduce((n,e)=>n+Math.max(0,e.delta-(e.streak||0)),0),room=Math.max(0,TIMO.dailyGainCap-gainedToday);if(g>room){g=room;notes.push('Limite giornaliero di recupero raggiunto');}
 let streak=0;if(!state.history.some(h=>dayKey(new Date(h.at))===dayKey())){const days=streakDays();if(days>=2){streak=Math.min(10,2*days);notes.push(`+${streak} costanza: ${days} giorni di fila`);}}
 return {gain:g+streak,streak,notes};}
const lifeTone=()=>state.timo.life>=70?['In equilibrio','Timo ha energia per crescere.']:state.timo.life>=40?['Da sostenere','Un allenamento può ridargli energia.']:['Ha bisogno di te','Scegli un piccolo allenamento per aiutarlo.'];
