function train(){return `${header('Allena la tua attenzione.','OTTO MODI PER COMINCIARE')}<p class="intro">Scegli cosa ti serve adesso. Ogni attività ha un inizio e una fine.</p><div class="catalog">${domains.map(activityCard).join('')}</div>`;}
function detailPage(){if(readingDomains.includes(detail))return libraryPage(detail);const d=activities[detail],selectedBook=state.activeBookId||state.books[0]?.id||null,readingReady=detail!=='lettura'||state.books.length>0;return `${header(d.name,'ALLENATI',true)}<section class="detail-hero d-${d.color}"><span class="activity-icon large">${icon(d.icon)}</span><h2>${d.verb}</h2><p>${d.description}</p><span class="meta">${d.time} · Una sessione alla volta</span></section>${detail==='lettura'?`<section class="card stack"><p class="eyebrow">LA TUA BIBLIOTECA</p><h2>${state.books.length?'Scegli dove continuare.':'Aggiungi il tuo primo libro.'}</h2>${state.books.length?`<label for="reading-source">Libro da leggere</label><select id="reading-source">${state.books.map(b=>`<option value="${esc(b.id)}" ${selectedBook===b.id?'selected':''}>${esc(b.title)} · ${b.pages} pagine</option>`).join('')}</select><p class="small muted">Si aprirà al segnalibro e potrai proseguire fino all’ultima pagina.</p>`:`<p class="muted">La lettura di Tempera usa esclusivamente i libri che scegli tu. Carica un file per iniziare: non verranno più mostrati testi sostitutivi.</p>`}<label class="secondary file-button">${icon('reading')} ${state.books.length?'Aggiungi un altro libro':'Importa un libro'}<input type="file" id="book-file" accept=".pdf,.epub,.txt" ${busy?'disabled':''}></label><p class="small muted">PDF con testo, EPUB o TXT · fino a 30 MB.<br>Il libro e il segnalibro restano su questo browser.</p></section>`:''}${['respirazione','meditazione'].includes(detail)?(()=>{const pk=choosePractice(detail,false);return `<section class="card practice-preview"><p class="eyebrow">SCELTA PER TE · 3 MINUTI</p><h3>${esc(pk.practice.variant)}</h3><p class="muted small">${esc(pk.practice.instruction)}</p><p class="small practice-why">${icon('focus')}<span>${esc(pk.reason[0].toUpperCase()+pk.reason.slice(1))}.</span></p></section>`;})():''}<section class="soft-note">${icon('focus')}<p>${detail==='lettura'?'Leggi al tuo ritmo. Alla fine scegli tu quando fermarti e quale pensiero conservare.':detail==='scacchi'?'Il Bianco muove. Usa la scacchiera oppure scrivi le coordinate della mossa.':detail==='respirazione'?'Segui l’icona al centro: si espande quando inspiri e si restringe quando espiri. Se il ritmo non è comodo, torna al tuo respiro naturale.':detail==='meditazione'?'Non devi svuotare la mente. Accorgerti di una distrazione fa parte della pratica.':'Nessuna corsa e nessuna penalità. Il feedback ti aiuta a capire e riprovare.'}</p></section>${button(busy?'Preparazione…':['respirazione','meditazione'].includes(detail)?'Inizia la pratica':'Comincia','start','primary wide',busy?'disabled':'')}`;}
const coverPalette=[['#3F604F','#F4F0E6'],['#74592B','#F7F1E3'],['#5A4F78','#F2EEF8'],['#3C5D66','#EAF2F4'],['#A04A38','#FBEDE7'],['#E9DFC8','#3B3326'],['#DCE7DF','#2E4A3C'],['#2B2E2A','#EDE8DA']];
function bookCover(b){if(b.cover)return `<img class="cover-img" src="${esc(b.cover)}" alt="" loading="lazy">`;const h=[...(b.title||'')].reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,7),[bg,ink]=coverPalette[h%coverPalette.length];return `<span class="gen-cover" style="--cover-bg:${bg};--cover-ink:${ink}">${b.author?`<small>${esc(b.author)}</small>`:''}<strong>${esc(b.title)}</strong><i></i></span>`;}
function bookStatus(b){const mark=state.bookmarks[b.id];if(!b.opened&&!(mark>0&&!b.starter))return '<span class="new-pill">NUOVO</span>';return `<span class="book-pct">${Math.max(1,Math.round(((mark||0)+1)/(b.pages||1)*100))}%</span>`;}
function libraryPage(shelf='lettura'){const prayer=shelf==='preghiera',books=booksFor(shelf).sort((a,b)=>(b.lastOpened||b.addedAt||'').localeCompare(a.lastOpened||a.addedAt||'')),current=booksFor(shelf).find(b=>b.id===state[activeKey(shelf)]);return `<div class="library-top">${button(icon('back'),'back','icon-button','aria-label="Indietro"')}<label class="icon-button add-book ${busy?'is-busy':''}" aria-label="Aggiungi un libro"><span aria-hidden="true">+</span><input type="file" id="book-file" accept=".pdf,.epub,.txt" ${busy?'disabled':''}></label></div><h1 class="library-title" tabindex="-1">${prayer?'Preghiera':'Libreria'}</h1>${books.length?`<p class="library-sub">${prayer?'Un tempo per ascoltare la Parola · ':''}${books.length} ${books.length===1?'libro':'libri'} · tocca una copertina per ${prayer?'iniziare':'leggere'}</p><div class="book-grid">${books.map(b=>`<article class="book-tile"><button class="book-cover" data-action="open-book" data-id="${esc(b.id)}" aria-label="Leggi ${esc(b.title)}">${bookCover(b)}</button><div class="book-meta">${bookStatus(b)}<details class="book-menu" ${pendingRemove===b.id?'open':''}><summary aria-label="Altre azioni per ${esc(b.title)}">•••</summary><div class="book-menu-pop">${pendingRemove===b.id?`<p class="confirm-text">Rimuovere questo libro? Il file sul tuo dispositivo non viene toccato.</p>${button('Sì, rimuovi','remove-book-confirm','menu-item danger',`data-id="${esc(b.id)}"`)}${button('Annulla','remove-book-cancel','menu-item')}`:button('Rimuovi dalla libreria','remove-book','menu-item danger',`data-id="${esc(b.id)}"`)}</div></details></div></article>`).join('')}<label class="book-tile add-tile"><span class="add-cover"><span>+</span><small>Aggiungi</small></span><input type="file" id="book-file-2" accept=".pdf,.epub,.txt" ${busy?'disabled':''}></label></div>${current?button(`${icon('reading')} Continua «${esc(current.title)}»`,'open-book','primary wide',`data-id="${esc(current.id)}"`):''}`:`<section class="library-empty"><div class="empty-shelf"><span></span><span></span><span></span></div><h2>${prayer?'Nessun testo per la preghiera.':'La tua libreria è vuota.'}</h2><p class="muted">${prayer?'Aggiungi la Bibbia, un salterio o un libro di preghiere in PDF, EPUB o TXT.':'Tempera usa solo i libri che scegli tu. Aggiungi un PDF, un EPUB o un TXT.'}</p><label class="primary wide file-button">${icon('reading')} ${busy?'Preparazione…':'Aggiungi il primo libro'}<input type="file" id="book-file" accept=".pdf,.epub,.txt" ${busy?'disabled':''}></label></section>`}<p class="small muted library-note">PDF con testo, EPUB o TXT · fino a 30 MB. I libri e i segnalibri restano solo su questo dispositivo.</p>`;}
function minutesControl(){return `<div class="segments" aria-label="Durata">${[1,3,5].map(n=>button(`${n} min`,'minutes',state.minutes===n?'selected':'',`data-id="${n}" aria-pressed="${state.minutes===n}"`)).join('')}</div>`;}
function preferences(){return `<div class="chips">${domains.map(id=>button(`${icon(activities[id].icon)}${activities[id].name}`,'favorite',state.favorites.includes(id)?'chip selected':'chip',`data-id="${id}" aria-pressed="${state.favorites.includes(id)}"`)).join('')}</div>`;}
function path(){return `${header('Dai forma al tuo ritmo.','IL TUO PERCORSO')}<section class="path-banner">${timo('small')}<div><h2>${esc(state.goal)}</h2><p class="muted">Un’intenzione da coltivare, un giorno alla volta.</p></div></section><section class="card stack"><h2>Le tue intenzioni</h2>${goalChoices()}</section><section class="card stack"><h2>Le tue attività</h2><p class="muted small">Tempera pesa orario, aperture ravvicinate, energia di Timo, tempo disponibile, varietà e storico recente. Poi estrae tra le attività più adatte, mantenendo una quota di sorpresa. Tutte rimangono disponibili in Allenati.</p>${preferences()}<p class="small muted">Respirazione e meditazione durano sempre 3 minuti. La tecnica viene scelta ogni volta in base alla tua attività recente.</p></section><section class="card stack"><h2>Prima dei social</h2><p class="muted">Scegli un’app per il passaggio diretto apertura → allenamento adattivo.</p><div class="chips">${Object.entries(social).filter(([,x])=>!x.generic).map(([id,s])=>button(s.name,'social',state.apps.includes(id)?'chip selected':'chip',`data-id="${id}" aria-pressed="${state.apps.includes(id)}"`)).join('')}</div>${button('Prova l’allenamento diretto','gate-direct','secondary',`data-id="${state.apps[0] || 'instagram'}"`)}<p class="small muted">Questa versione web non blocca altre app. Il collegamento seguente apre direttamente un esercizio e registra un tentativo di accesso.</p><details open><summary>URL per Comandi Rapidi</summary><code class="url">${esc(location.origin+location.pathname)}?trigger=${state.apps[0] || 'instagram'}&amp;direct=1</code>${button('Copia URL diretto','copy-link','secondary')}<p class="small muted">Facoltativo: aggiungi <strong>&amp;context=work</strong>, <strong>break</strong> o <strong>bedtime</strong>, e <strong>&amp;available=2</strong> per comunicare i minuti disponibili. Per registrare il tempo su Instagram, usa <strong>/?report=instagram&amp;minutes=NUMERO</strong>.</p></details></section><section class="card stack"><h2>Come vive Timo</h2><p class="small muted">Timo è pensato per non farsi ingannare: ciò che conta è la costanza e la qualità, non la quantità.</p>
<div class="rules"><div><p class="eyebrow">PERDE ENERGIA</p><ul>
<li><span>Apertura di un social</span><strong>−4 → −15</strong><small>Cresce se le aperture sono ravvicinate (nell’ora); di notte vale una volta e mezzo.</small></li>
<li><span>“Continuo su…” senza pausa</span><strong>−${TIMO.bypass}</strong></li>
<li><span>Minuti social del giorno</span><strong>progressivo</strong><small>Primi 15 liberi · 15–30: −1 ogni 2 min · 30–60: −1 al minuto · oltre 60: −2 al minuto.</small></li>
<li><span>Allenamento lasciato a metà</span><strong>−${TIMO.abandon}</strong></li>
<li><span>Un giorno senza allenamenti</span><strong>−${TIMO.inactiveDay}</strong></li></ul></div>
<div><p class="eyebrow">RECUPERA ENERGIA</p><ul>
<li><span>Matematica, logica, memoria, scacchi</span><strong>+${TIMO.base.cognitive}</strong></li>
<li><span>Lettura o preghiera con domande</span><strong>+${TIMO.base.readingQuiz}</strong><small>Senza domande: +${TIMO.base.reading}.</small></li>
<li><span>Respirazione e meditazione complete</span><strong>+${TIMO.base.practice}</strong></li>
<li><span>Tutto giusto al primo tentativo</span><strong>+${TIMO.perfect}</strong></li>
<li><span>Allenamento nato da un impulso social</span><strong>+${TIMO.trigger}</strong></li>
<li><span>Costanza (giorni di fila con ≤30 min social)</span><strong>fino a +10</strong></li></ul></div></div>
<p class="small">Per non “ricaricare” Timo di fretta: nelle 24 ore i guadagni scendono al 70%, 50% e 25%; si recuperano al massimo ${TIMO.dailyGainCap} punti al giorno; esercizi svolti troppo in fretta o a tentativi valgono poco o nulla.</p>
${(()=>{const ev=state.timo.events.slice(-8).reverse();return ev.length?`<div class="timo-log"><p class="eyebrow">ULTIMI MOVIMENTI</p>${ev.map(e=>`<div class="${e.delta<0?'minus':'plus'}"><span>${esc(e.note||({access:'Apertura',social:'Tempo social',training:'Allenamento',bypass:'Pausa saltata',abandon:'Allenamento lasciato',inactive:'Giorno senza allenamenti'}[e.type]||e.type))}<small>${new Date(e.at).toLocaleString('it-IT',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</small></span><strong>${e.delta>0?'+':''}${e.delta}</strong></div>`).join('')}</div>`:'';})()}</section><section class="card"><h2>Le tue tappe</h2><ol class="milestones"><li class="complete"><strong>Trova un’intenzione</strong><span>Hai scelto da dove partire.</span></li><li class="${total()?'complete':''}"><strong>Dedica il primo momento</strong><span>${total()?'Il tuo percorso è cominciato.':'Una sessione è un punto di partenza.'}</span></li><li class="${state.history.length>=7?'complete':''}"><strong>Ritrova il tuo ritmo</strong><span>${Math.min(state.history.length,7)} di 7 sessioni nella nuova versione. Senza scadenze.</span></li></ol></section>`;}
function progress(){const recent=state.history.slice(-12).reverse(),days=Array.from({length:7},(_,i)=>{const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-6+i);return d;}),rows=days.map(d=>({date:d,...dailyRow(d)})),sum=key=>rows.reduce((n,r)=>n+(Number(r[key])||0),0),sessions=sum('sessions'),attempts=sum('accessAttempts'),directDone=sum('directCompleted'),practice=sum('practiceSeconds'),socialMinutes=sum('socialMinutes'),correct=sum('correct'),answers=sum('answers'),conversion=attempts?Math.round(directDone/attempts*100):0,accuracy=answers?Math.round(correct/answers*100):null,resistanceSessions=sum('resistanceSessions'),avgResistance=resistanceSessions?(sum('resistanceTotal')/resistanceSessions).toFixed(1):'—',timoDelta=sum('timoDelta'),maxBar=Math.max(1,...rows.flatMap(r=>[r.accessAttempts,r.directCompleted]));return `${header('Il tuo rapporto con l’attenzione.','I TUOI PROGRESSI')}<p class="intro">Qui osservi cosa accade tra l’impulso di aprire un social e la scelta che fai dopo. I dati restano su questo browser.</p><div class="stats-grid analytics-summary"><section class="card"><span class="stat">${attempts}</span><span>Impulsi intercettati</span></section><section class="card"><span class="stat">${directDone}</span><span>Trasformati in allenamento</span></section><section class="card"><span class="stat">${Math.floor(practice/60)}<small> min</small></span><span>Tempo di pratica</span></section><section class="card"><span class="stat">${socialMinutes}<small> min</small></span><span>Tempo social comunicato</span></section></div><section class="card analytics-chart"><div class="row spread"><div><p class="eyebrow">ULTIMI 7 GIORNI</p><h2>Impulsi e scelte</h2></div><div class="chart-legend"><span><i class="attempt"></i>Impulsi</span><span><i class="trained"></i>Allenamenti</span></div></div><div class="behavior-bars">${rows.map(r=>`<div class="behavior-day" title="${r.date.toLocaleDateString('it-IT')}: ${r.accessAttempts} impulsi, ${r.directCompleted} allenamenti"><div class="bar-pair"><i class="attempt" style="height:${Math.max(r.accessAttempts?8:0,r.accessAttempts/maxBar*100)}%"></i><i class="trained" style="height:${Math.max(r.directCompleted?8:0,r.directCompleted/maxBar*100)}%"></i></div><span>${r.date.toLocaleDateString('it-IT',{weekday:'short'}).slice(0,2)}</span></div>`).join('')}</div><p class="small muted">${attempts?`${conversion}% degli impulsi è diventato un momento di allenamento (${directDone} su ${attempts}).`:'Quando userai il collegamento dei Comandi Rapidi, qui vedrai il rapporto tra impulsi e allenamenti.'}</p></section><section class="card"><p class="eyebrow">QUALITÀ DELLA SETTIMANA</p><div class="signal-list"><div><span>Scelte consapevoli</span><strong>${conversion}%</strong><small>allenamenti diretti ÷ impulsi</small></div><div><span>Precisione cognitiva</span><strong>${accuracy===null?'—':accuracy+'%'}</strong><small>risposte corrette ÷ tentativi</small></div><div><span>Resistenza media</span><strong>${avgResistance}</strong><small>su 4 nei percorsi social</small></div><div><span>Energia di Timo</span><strong>${timoDelta>0?'+':''}${timoDelta}</strong><small>saldo degli ultimi 7 giorni</small></div></div></section><section class="card"><h2>Le tue direzioni</h2>${domains.map(id=>`<div class="domain-stat d-${activities[id].color}"><span class="activity-icon">${icon(activities[id].icon)}</span><span>${activities[id].name}</span><strong>${count(id)}</strong></div>`).join('')}<p class="small muted">Sessioni completate per attività. Il totale storico è ${total()}.</p></section>${state.baseline.completed?`<section class="notice"><strong>${state.baseline.completed} sessioni precedenti conservate</strong><p class="small">Sono incluse nel totale. La vecchia versione non registrava dettagli giornalieri, quindi non vengono attribuiti a date o metriche non documentate.</p></section>`:''}<div class="section-title"><h2>Momenti recenti</h2></div>${recent.length?`<div class="card">${recent.map(s=>`<div class="history-row"><div><strong>${activities[s.domain]?.name || 'Allenamento'}</strong><p class="small muted">${new Date(s.at).toLocaleDateString('it-IT',{day:'numeric',month:'long'})} · ${duration(s.seconds)}${s.trigger?` · Livello ${s.resistanceLevel||1}`:''}</p>${s.note?`<p class="reflection">${esc(s.note)}</p>`:''}</div>${icon('check')}</div>`).join('')}</div>`:`<section class="empty card">${icon('progress')}<h3>Qui troverai il tuo percorso.</h3><p>Impulsi e sessioni completate appariranno qui.</p>${button('Scegli un’attività','train','secondary')}</section>`}`;}
function settings(){return `${header('Uno spazio che ti somiglia.','IMPOSTAZIONI',true)}<section class="card stack"><h2>Aspetto</h2><label for="theme">Tema dell’interfaccia</label><select id="theme">${[['system','Come il dispositivo'],['light','Chiaro'],['dark','Scuro']].map(([v,t])=>`<option value="${v}" ${state.theme===v?'selected':''}>${t}</option>`).join('')}</select><p class="small muted">Tempera rispetta l’impostazione “riduci movimento” del dispositivo.</p></section><section class="card stack"><h2>I tuoi dati</h2><p>Libri, intenzione e progressi sono salvati in questo browser. Non si sincronizzano tra dispositivi.</p>${button('Esporta progressi e preferenze','export','secondary')}<p class="small muted">L’esportazione non contiene il testo dei libri: conserva anche i file originali. Cancellare i dati del browser elimina i salvataggi locali.</p></section><section class="card stack"><h2>Come funziona</h2><p>Scegli un’attività, dedica un momento alla pratica e decidi come continuare.</p><p class="muted">Il sito non può bloccare altre app o misurare il tempo trascorso sui social. I progressi descrivono la tua pratica, non una valutazione delle capacità cognitive.</p><p class="meta">Tempera · Nuova interfaccia 2.0</p></section>`;}
function onboardingPage(){const headings=['Un momento per te.','Che cosa vuoi ritrovare?','Scegli da dove partire.'];return `<div class="onboard"><div class="topbar"><span class="brand"><span class="brandmark">${mark}</span>Tempera</span><span class="meta">${onboarding+1} / 3</span></div><div class="step-dots">${[0,1,2].map(n=>`<span class="${n<=onboarding?'active':''}"></span>`).join('')}</div>${onboarding===0?timo():''}${header(headings[onboarding],'PICCOLI GESTI, PIÙ ATTENZIONE')}${onboarding===0?`<p class="intro">Trasforma l’impulso di scorrere in un momento di lettura, ragionamento o presenza.</p><section class="card"><div class="journey"><span>Un impulso</span><b>→</b><span>Una pausa</span><b>→</b><span>Una scelta</span></div><p class="small muted">Puoi allenarti quando vuoi. Questa versione web non blocca le altre app.</p></section>`:onboarding===1?`<p class="intro">Scegli una o più direzioni che senti vicine. Potrai cambiarle quando vuoi nel Percorso.</p>${goalChoices()}`:`<p class="intro">Le attività selezionate si alterneranno nella tua Home.</p>${preferences()}`}<div class="onboard-actions">${button(onboarding===2?'Entra in Tempera':'Continua','onboard-next','primary wide',onboarding===1&&!state.goals.length?'disabled':'')}${onboarding?button('Indietro','onboard-back','text-button'):''}</div></div>`;}
function gate(){const id=trigger || state.apps[0] || 'instagram';return `${header('Prima di aprire '+social[id].name,'UN MOMENTO DI SCELTA',true)}<div class="gate-scene">${timo()}<h2>Era un’intenzione<br>o un automatismo?</h2><p class="muted">Dedica un piccolo spazio a te.<br>Poi scegli liberamente come continuare.</p></div>${button('Mi prendo questo momento','gate-start','primary wide',`data-id="${id}"`)}${button('Scelgo un’altra attività','gate-catalog','secondary wide',`data-id="${id}"`)}<a class="text-button centered" data-action="gate-bypass" data-id="${id}" href="${social[id].url}" rel="noopener">Continuo su ${social[id].name} · Timo −${TIMO.bypass}</a><p class="small muted centered">Nessun accesso viene bloccato, ma saltare la pausa costa energia a Timo.</p>`;}
async function start(){if(busy)return;if(session){view='replace';render();return;}await createSession();}
async function createSession(){busy=true;notice='';render();try{const d=detail,profile=trigger?directProfile():{level:1,...resistanceProfiles[1],minutes:state.minutes,label:'Volontaria'},s={id:crypto.randomUUID(),createdAt:Date.now(),domain:d,seconds:0,index:0,attempts:0,correct:0,phase:'active',trigger,questions:[],running:false,resistance:profile};
 if(readingDomains.includes(d)){s.readingPrompt=chooseFresh(d==='preghiera'?prayerPrompts:readingPrompts,1,d+'-riflessioni')[0];const source=(booksFor(d).some(b=>b.id===state[activeKey(d)])&&state[activeKey(d)])||booksFor(d)[0]?.id||null;if(!source)throw new Error('Importa un libro completo prima di iniziare la lettura.');const book=await getBook(source);if(!book?.pages?.length)throw new Error('Il testo di questo libro non è disponibile in questo browser. Importa nuovamente il file originale.');const meta=state.books.find(b=>b.id===source);state[activeKey(d)]=source;s.bookId=source;s.kind=book.kind||'text';s.page=Math.min(state.bookmarks[source]??meta?.startPage??0,book.pages.length-1);s.startPage=s.page;s.pagesRead=[s.page];s.requiredPages=Math.min(profile.pages,book.pages.length);s.title=book.title || state.books.find(b=>b.id===source)?.title;s.text=book.pages[s.page]||'';s.html=book.html?.[s.page]||'';s.pageCount=book.pages.length;s.phase='read';tocOpen=false;persist();}
 const required=trigger?profile.questions:3;if(d==='matematica')s.questions=chooseFresh(mathQuestions(60),required,'matematica');if(d==='logica')s.questions=chooseFresh(logicQuestions(60),required,'logica');if(d==='memoria'){s.round=0;s.totalRounds=required;const m=freshMemory();s.sequence=m.sequence;s.memoryVariant=m.variant;Object.assign(s,memoryFields(m));s.recalled=[];s.phase='memorize';}if(d==='scacchi'){s.round=0;s.totalRounds=required;s.puzzles=chooseFresh(chessPuzzles,required,'scacchi');s.puzzle=s.puzzles[0];chessSetup(s);}if(['respirazione','meditazione'].includes(d)){const pick=choosePractice(d);s.practice=pick.practice;s.practiceReason=pick.reason;s.target=PRACTICE_SECONDS;s.phase='ready';}if(trigger&&profile.level>=2){s.exercisePhase=s.phase;s.phase='intent';}session=s;selection=null;feedback=null;persistSession();view='session';}catch(e){notice=e.message;}finally{busy=false;render();window.scrollTo({top:0});}}
async function loadBookPage(page){if(!session?.bookId)return;const book=await getBook(session.bookId);tocOpen=false;if(!book?.pages?.length)throw new Error('Il testo del libro non è più disponibile in questo browser.');session.page=Math.min(book.pages.length-1,Math.max(0,Number(page)||0));session.text=book.pages[session.page]||'';session.html=book.html?.[session.page]||'';session.pageCount=book.pages.length;session.pagesRead=[...new Set([...(session.pagesRead||[]),session.page])];state.bookmarks[session.bookId]=session.page;persist();persistSession();render();window.scrollTo({top:0});}
function resistanceScreen(s){const r=s.resistance;if(s.phase==='intent')return `<div class="resistance-step"><p class="eyebrow">ACCESSO CONSAPEVOLE · LIVELLO ${r.level}</p><h1 tabindex="-1">Perché vuoi aprire ${social[s.trigger]?.name||'questa app'}?</h1><p class="muted">La risposta non viene giudicata. Serve a interrompere l’automatismo prima dell’allenamento.</p><div class="answers">${[['messaggio','Devo rispondere a qualcuno'],['pubblicare','Devo pubblicare qualcosa'],['pausa','Sto cercando una pausa'],['abitudine','L’ho aperta per abitudine']].map(([id,label])=>button(label,'intent-choice','answer',`data-id="${id}"`)).join('')}</div><div class="resistance-summary">${icon('block')}<span>Resistenza ${r.label}: ${r.questions} prove, ${r.pages} pagine oppure ${r.minutes} min di pratica.</span></div></div>`;
 if(s.phase==='access-reflect')return `<div class="resistance-step"><p class="eyebrow">PRIMA DELLA SCELTA · LIVELLO ${r.level}</p><h1 tabindex="-1">Che cosa vuoi fare quando entri?</h1><p class="muted">Scrivi un’intenzione concreta. Ti verrà ricordata prima dell’accesso.</p><label for="access-intention">La mia intenzione</label><textarea id="access-intention" rows="3" maxlength="180" placeholder="Per esempio: rispondo al messaggio e poi esco.">${esc(s.accessIntention||'')}</textarea>${button('Continua','access-reflect-done','primary wide')}</div>`;
 if(s.phase==='access-wait'){const left=Math.max(0,20-Math.floor(s.waitElapsed||0));return `<div class="resistance-step waiting"><p class="eyebrow">ULTIMO PASSAGGIO · LIVELLO 4</p><h1 tabindex="-1">Lascia passare ancora un momento.</h1><div class="wait-ring"><strong id="wait-count">${left}</strong><span>secondi</span></div><p class="muted">La tua intenzione: “${esc(s.accessIntention)}”</p>${button(left?'Attendi…':'Confermo la mia scelta','access-confirm','primary wide',left?'disabled':'')}</div>`;}return '';
}
function readingGate(s){const read=(s.pagesRead||[]).length,required=s.requiredPages||1,left=Math.max(0,required-read);return `<div class="reading-requirement ${left?'':'met'}">${left?`${icon('reading')} <span>Leggi ancora ${left} ${left===1?'pagina':'pagine'} per completare questo accesso.</span>`:`${icon('check')} <span>Requisito raggiunto: ${read} pagine lette.</span>`}</div>`;}
function sessionPage(){const s=session;if(!s){view='today';return today();}const reading=s.phase==='read',totalSteps=reading?0:(s.questions.length||s.totalRounds||0),currentStep=totalSteps?(s.index??s.round)+1:0,special=resistanceScreen(s),sessionMeta=special?`Livello ${s.resistance.level}`:reading?`Pagina ${s.page+1} di ${s.pageCount}`:(totalSteps?currentStep+' / '+totalSteps:'Il tuo momento');return `<div class="session-top">${button(icon('back'),'exit','icon-button','aria-label="Metti in pausa e torna alla Home"')}${badge(s.domain)}<span class="meta">${sessionMeta}</span></div><div class="progress-line"><span style="width:${special?20:reading?Math.round(((s.pagesRead||[]).length/(s.requiredPages||1))*100):totalSteps?Math.round(((currentStep-1)/totalSteps)*100):25}%"></span></div><div class="session-body">${special||(penaltyLeft()&&['active','recall'].includes(s.phase)&&!['respirazione','meditazione'].includes(s.domain)?penaltyScreen(s):exerciseBody(s))}</div>`;}
async function hydrateReader(){const s=session;if(!s||view!=='session'||s.phase!=='read')return;try{
 if(readerCache.id!==s.bookId){await getBook(s.bookId);if(session===s)render();return;}
 const book=readerCache.book;document.querySelectorAll('#reading-page img[data-img]').forEach(img=>{const d=book?.images?.[img.dataset.img];if(d&&!img.src)img.src=d;});
 if(s.kind!=='pdf')return;
 if(readerMode(s)==='text'){if(!s.text){const pdf=await getPdf();if(!pdf)return;const page=s.page,text=await pdfPageText(pdf,page);if(session!==s||s.page!==page)return;s.text=text||'(Questa pagina contiene solo un’illustrazione: tocca ▣ per vederla.)';persistSession();render();}return;}
 const canvas=document.querySelector('#pdf-canvas');if(!canvas)return;if(!book?.file){canvas.parentElement.querySelector('.pdf-loading').textContent='Per vedere la pagina originale, rimuovi questo libro e aggiungilo di nuovo.';return;}
 const pdf=await getPdf(),page=await pdf.getPage(s.page+1),box=canvas.parentElement.clientWidth,base=page.getViewport({scale:1}),dpr=Math.min(3,window.devicePixelRatio||1),vp=page.getViewport({scale:box/base.width*dpr*1.35});
 if(!document.contains(canvas)){hydrateReader();return;}
 // Disegna la pagina fuori schermo, trova i margini bianchi e mostra solo l’area stampata (stabile per tutto il libro).
 const off=document.createElement('canvas');off.width=Math.floor(vp.width);off.height=Math.floor(vp.height);const octx=off.getContext('2d',{willReadFrequently:true});octx.fillStyle='#fff';octx.fillRect(0,0,off.width,off.height);readerCache.task?.cancel?.();readerCache.task=page.render({canvasContext:octx,viewport:vp});await readerCache.task.promise;if(!document.contains(canvas)){hydrateReader();return;}
 const W=off.width,H=off.height,data=octx.getImageData(0,0,W,H).data;let x0=W,y0=H,x1=0,y1=0;for(let y=0;y<H;y+=2)for(let x=0;x<W;x+=2){const i=(y*W+x)*4;if(data[i]<225||data[i+1]<225||data[i+2]<225){if(x<x0)x0=x;if(x>x1)x1=x;if(y<y0)y0=y;if(y>y1)y1=y;}}
 let crop=readerCache.crop;if(x1>x0){const f={l:x0/W,r:x1/W,t:y0/H,b:y1/H};crop=crop?{l:Math.min(crop.l,f.l),r:Math.max(crop.r,f.r),t:Math.min(crop.t,f.t),b:Math.max(crop.b,f.b)}:f;readerCache.crop=crop;}
 const pad=.035,L=crop?Math.max(0,crop.l-pad):0,R=crop?Math.min(1,crop.r+pad):1,T=crop?Math.max(0,crop.t-pad*.7):0,B=crop?Math.min(1,crop.b+pad*.7):1,sw=Math.round((R-L)*W),sh=Math.round((B-T)*H);
 canvas.width=sw;canvas.height=sh;canvas.style.aspectRatio=`${sw}/${sh}`;canvas.getContext('2d').drawImage(off,Math.round(L*W),Math.round(T*H),sw,sh,0,0,sw,sh);canvas.parentElement.classList.add('ready');}catch(e){if(e?.name!=='RenderingCancelledException'){notice=e.message||'Non riesco ad aprire questa pagina.';}}}
async function quizFor(s){const book=await getBook(s.bookId),n=book.pages.length,read=[...new Set(s.pagesRead?.length?s.pagesRead:[s.page])].sort((a,b)=>a-b).slice(-8),last=read[read.length-1],far=last+6<n?last+6:Math.max(0,read[0]-6);
 let texts,other;if(book.kind==='pdf'){const pdf=await getPdf();texts=[];for(const p of read)texts.push(await pdfPageText(pdf,p));other=[await pdfPageText(pdf,far)];if(far+1<n)other.push(await pdfPageText(pdf,far+1));}else{texts=read.map(p=>book.pages[p]||'');other=[book.pages[far]||'',book.pages[far+1]||''];}
 let readText=texts.join('\n\n');if(readText.replace(/\s/g,'').length<500&&last+1<n)readText+='\n\n'+(book.kind==='pdf'?await pdfPageText(await getPdf(),last+1):book.pages[last+1]||'');
 return makeReadingQuiz(readText,other.join('\n\n'),s.trigger?Math.min(5,s.resistance?.questions||3):3);}
const READING_SECONDS=120;
function readTimer(s){const left=Math.max(0,Math.ceil(READING_SECONDS-s.seconds)),quiz=!s.quizDone;return `<div class="read-timer ${left?'':'done'}" id="read-timer"><span id="read-timer-label">${left?`Tempo di lettura <strong>${duration(left)}</strong>`:'Tempo di lettura completato'}</span><span class="read-timer-bar"><i id="read-timer-bar" style="width:${Math.min(100,s.seconds/READING_SECONDS*100)}%"></i></span></div>${button(left?'Leggi ancora un po’…':(quiz?'Vai alle domande':'Continua'),'read-done','primary wide',left?'disabled':'')}`;}
function readerParagraphs(s){let dropped=s.page!==0;return s.text.split(/\n\s*\n/).map(p=>p.trim()).filter(Boolean).map(p=>{if(p.length<70&&!/[.,;:!?…»”]$/.test(p))return `<h2 class="chapter-head">${esc(p)}</h2>`;const cls=!dropped&&p.length>80?' class="dropcap"':'';if(cls)dropped=true;return `<p${cls}>${esc(p)}</p>`;}).join('');}
function exerciseBody(s){if(s.phase==='read'){const pdf=s.kind==='pdf',mode=readerMode(s),book=state.books.find(b=>b.id===s.bookId);let body;
  if(pdf&&mode==='original')body=`<div class="pdf-page" id="reading-page"><canvas id="pdf-canvas" role="img" aria-label="Pagina ${s.page+1} del libro"></canvas><span class="pdf-loading">Sto aprendo la pagina…</span></div>`;
  else if(s.html)body=`<article class="reading-surface rich" id="reading-page" lang="it">${s.html}</article>`;
  else if(pdf&&!s.text)body=`<article class="reading-surface" id="reading-page"><p class="muted centered pdf-text-loading">Sto preparando il testo…</p></article>`;
  else body=`<article class="reading-surface ${s.page===0?'first-page':''}" id="reading-page" lang="it">${readerParagraphs(s)}</article>`;
  const toc=readerCache.id===s.bookId?readerCache.book?.toc||[]:[];
  return `<div class="reader ${pdf&&mode==='original'?'is-original':''}"><div class="reader-top">${toc.length?button(`${icon('menu')}<span>Indice</span>`,'reader-toc','reader-tool',`aria-expanded="${tocOpen}"`):'<span></span>'}<p class="reader-title">${esc(s.title)}</p>${pdf?button(mode==='original'?'<span>Aa</span>':'<span>▣</span>','reader-mode','reader-tool',`aria-label="${mode==='original'?'Passa al testo adattato':'Torna alla pagina originale'}" title="${mode==='original'?'Testo adattato':'Pagina originale'}"`):'<span></span>'}</div>${tocOpen&&toc.length?`<nav class="toc-sheet" aria-label="Indice"><p class="eyebrow">INDICE</p><ol>${toc.map(t=>`<li class="lvl-${Math.min(2,t.level||0)} ${t.page<=s.page&&!(toc.find(x=>x.page>t.page&&x.page<=s.page))?'current':''}">${button(`<span>${esc(t.title)}</span><small>${t.page+1}</small>`,'toc-go','toc-item',`data-id="${t.page}"`)}</li>`).join('')}</ol></nav>`:''}${body}${pdf&&mode==='original'?'':`<p class="reader-folio">${s.page+1}</p>`}<div class="reader-bar">${button(icon('back'),'book-prev','icon-button',`aria-label="Pagina precedente" ${s.page===0?'disabled':''}`)}<label class="reader-scrub"><span class="sr-only">Vai alla pagina</span><input type="range" id="book-page" min="0" max="${s.pageCount-1}" value="${s.page}" aria-valuetext="Pagina ${s.page+1} di ${s.pageCount}"><small>${s.page+1} di ${s.pageCount} · ${Math.round((s.page+1)/s.pageCount*100)}%</small></label>${button(icon('next'),'book-next','icon-button',`aria-label="Pagina successiva" ${s.page===s.pageCount-1?'disabled':''}`)}</div>${readTimer(s)}<p class="small muted centered">${pdf&&mode==='original'?'Stai vedendo la pagina originale del file. Tocca “Aa” per il testo adattato allo schermo.':'Scorri a destra o a sinistra per cambiare pagina.'}${book?.credit?`<br>${esc(book.credit)}`:''}</p></div>`;}
 if(s.phase==='reflect')return `${s.domain==='preghiera'?header('Che cosa ti ha parlato?','LA TUA PREGHIERA'):header('Cosa ti rimane?','LA TUA LETTURA')}<section class="reflection-prompt"><span>${icon('reading')}</span><div><p class="eyebrow">SPUNTO DI QUESTA SESSIONE</p><strong>${esc(s.readingPrompt||readingPrompts[0])}</strong></div></section><p class="muted">Lo spunto cambia a ogni sessione. Non esiste una risposta da valutare.</p><label for="reflection">La tua riflessione (facoltativa)</label><textarea id="reflection" rows="4" maxlength="1500" placeholder="Porto con me…">${esc(s.note || '')}</textarea>${button('Concludi la lettura','finish-reading','primary wide')}`;
 if(s.phase==='feedback'){const hasNext=s.questions.length?s.index<s.questions.length-1:(s.totalRounds||1)>((s.round||0)+1);return `<div class="result-inline">${icon('check')}<p class="eyebrow">UN PASSAGGIO ALLA VOLTA</p><h1 tabindex="-1">Hai trovato la strada.</h1><p>${esc(s.explanation)}</p>${button(hasNext?'Prossima prova':'Concludi la sessione','next-question','primary wide')}</div>`;}
 if(['respirazione','meditazione'].includes(s.domain))return timerPage(s);if(s.domain==='memoria')return memoryPage(s);if(s.domain==='scacchi')return chessPage(s);
 const q=s.questions[s.index];return `<p class="eyebrow">${esc(q.variant||(s.domain==='lettura'?'COMPRENSIONE':s.domain==='logica'?'COLLEGA LE IDEE':'CALCOLO QUOTIDIANO'))}</p><h1 class="question" tabindex="-1">${esc(q.q)}</h1>${q.choices?`<div class="answers">${q.choices.map((c,i)=>button(`<span class="answer-letter">${String.fromCharCode(65+i)}</span>${esc(c)}`,'answer',selection===i?'answer selected':'answer',`data-id="${i}" aria-pressed="${selection===i}"`)).join('')}</div>`:`<form id="math-form"><label for="number-answer">La tua risposta</label><input id="number-answer" inputmode="decimal" autocomplete="off" placeholder="Scrivi un numero" aria-describedby="answer-feedback"><button class="primary wide" type="submit">Verifica</button></form>`}${feedback?`<div class="notice" id="answer-feedback" role="status">${feedback}</div>`:'<span id="answer-feedback"></span>'}${q.choices?button('Verifica','verify','primary wide',selection===null?'disabled':''):''}${s.quizMode?`${button('Rileggi le pagine','reread','text-button')}${button('Salta le domande','quiz-skip','text-button')}`:''}`;}
